return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'uz_UZ','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T07:20:29+00:00','po-revision-date'=>'2026-09-26T07:20:29+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','The foundation release of the rebuilt Tranzly: a list of your site\'s languages, a language switcher block, and the language API other plugins read.'=>'Qayta qurilgan Tranzly\'ning ilk asosi: saytingiz tillari ro‘yxati, tilni almashtirish bloki va boshqa plaginlar o‘qiydigan til API\'si.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'SUN yetkazib beruvchilari','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT yaratuvchilari. Yaxshi universal yechim.','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude yaratuvchilari. Matn yozish va sinchkovlik bilan fikrlashda kuchli.','Google\'s Gemini models. Fast and inexpensive.'=>'Google ning Gemini modellari. Tez va arzon.','A European AI company with fast, inexpensive models.'=>'Tezkor va arzon modellarga ega bo\'lgan Yevropa sun\'iy intellekt kompaniyasi.','Low-cost models that are good at writing and code.'=>'Yozish va dasturlashda yaxshi ishlaydigan arzon modellar.','One key for models from many different providers.'=>'Turli provayderlardagi modellar uchun bitta kalit.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'OpenAI API kabi ishlaydigan har qanday xizmat, shu jumladan o\'z kompyuteringiz yoki serveringizda ishlaydigan model.','General (used when nothing more specific is set)'=>'Umumiy (boshqa aniqroq sozlama boʻlmaganda ishlatiladi)','Writing and rewriting'=>'Yozish va qayta yozish','Translation'=>'Tarjima','Code and CSS'=>'Kod va CSS','Sorry, you are not allowed to access this page.'=>'Kechirasiz, ushbu sahifaga kirishga ruxsatingiz yo\'q.','These settings are shared by every plugin that uses them: %s.'=>'Ushbu sozlamalar ulardan foydalanadigan har bir plagin uchun umumiy hisoblanadi: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Kalitlaringiz ushbu sayt maʼlumotlar bazasida shifrlangan va faqat siz tanlagan provayderga yuboriladi — hech qachon bizga emas.','Step 1 of 2: choose an AI provider'=>'1-qadam (jami 2): sun\'iy intellekt provayderini tanlang','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Siz oʻz kalitingizdan foydalanasiz, shuning uchun ishlatilgan hajm uchun toʻlovni toʻgʻridan-toʻgʻri provayderga amalga oshirasiz. Ikkilanyapsizmi? Bularning har biri yaxshi ishlaydi; keyinchalik yana qoʻshishingiz mumkin.','Next'=>'Keyingi','Step 2 of 2: connect %s'=>'2-qadam: %s ni ulang','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'/v1 bilan tugaydigan OpenAI bilan mos keluvchi xizmatingiz manzilini kiriting. Kalit faqat xizmat uni talab qilgandagina kerak bo\'ladi.','Open %s and sign in (or create a free account).'=>'%s ni oching va tizimga kiring (yoki bepul hisob yarating).','the %s API keys page'=>'%s API kalitlari sahifasi','Create a new key and copy it.'=>'Yangi kalit yarating va uni nusxalang.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Uni quyiga qo\'ying va "Saqlash va sinovdan o\'tkazish" tugmasini bosing. Uning ishlashini tekshirish uchun biz bitta kichik so\'rov yuboramiz.','Most providers need a little credit on the account before a key works: %s.'=>'Aksariyat provayderlar kalit ishlashi uchun hisobda ozgina mablag‘ talab qiladi: %s.','add credit'=>'balansni to‘ldirish','← Choose a different provider'=>'← Boshqa provayderni tanlang','Address'=>'Manzil','Saved key ends in …%s — paste a new one to replace it'=>'Saqlangan kalit …%s bilan tugaydi — uning o\'rniga yangisini qo\'ying','Key (optional)'=>'Kalit (ixtiyoriy)','API key'=>'API kaliti','Save and test'=>'Saqlash va sinovdan o\'tkazish','Providers'=>'Ta\'minotchilar','Provider'=>'Provayder','Status'=>'Holat','Key'=>'Kalit','Get a key'=>'Kalit olish','Test'=>'Sinov','Remove'=>'O\'chirish','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Yangiroq plagin versiyasi tomonidan saqlangan: ushbu plaginni yangilang yoki kalitni qaytadan kiriting.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Saqlangan kalitni endi ochib bo\'lmaydi (saytning xavfsizlik kalitlari o\'zgargan). Uni qayta kiriting.','Not connected'=>'Ulanmagan','Connected — last test passed %s'=>'Ulangan — oxirgi sinovdan o\'tdi %s','Last test failed: %s'=>'Oxirgi sinov muvaffaqiyatsiz tugadi: %s','Connected — not tested yet'=>'Ulangan — hali sinovdan oʻtkazilmagan','Which model to use'=>'Qaysi modeldan foydalanish kerak','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ bu vazifa uchun tavsiyamizni bildiradi. Ro\'yxat kalitingiz foydalanishi mumkin bo\'lgan har bir modelni o\'z ichiga oladi va ular provayderdan jonli ravishda o\'qib olinadi.','— Recommended for the provider —'=>'— Provayder uchun tavsiya etiladi —','Save models'=>'Modellarni saqlash','Refresh the model lists from the providers'=>'Provayderlardan model ro\'yxatlarini yangilash','best quality'=>'eng yaxshi sifat','lowest cost'=>'eng arzon','fastest'=>'eng tezkor','Add a model yourself'=>'O\'zingiz model qo\'shing','A model came out today? Paste its exact name to use it straight away.'=>'Bugun yangi model chiqdimi? Uni darhol ishlatish uchun aniq nomini kiriting.','Model name'=>'Model nomi','Add model'=>'Model qo\'shish','Recommended models list'=>'Tavsi etilgan modellar ro\'yxati','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Tavsiya etilgan modellar roʻyxatini tekshirib boʻlmadi, shuning uchun hech qanday tavsiya koʻrsatilmagan. Plaginni qayta oʻrnating yoki quyida kundalik yangilanishlarni yoqing.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Foydalanilayotgan roʻyxat %s da eʼlon qilingan. Har bir plagin yangilanishi yangisini olib keladi.','Also check Zinn Digital® once a day for an updated list.'=>'Yangilangan ro‘yxat uchun Zinn Digital® saytini kuniga bir marta tekshirib turing.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Faqat oddiy yuklab olish soʻrovi yuboriladi: kalit ham, sayt manzili ham, kontentingiz haqida hech qanday maʼlumot ham yoʻq. Roʻyxat imzolanadi va imzo tekshiruvidan oʻta olmagan roʻyxat eʼtiborga olinmaydi.','Last checked %1$s: %2$s.'=>'Oxirgi marta tekshirilgan %1$s: %2$s.','Save, and check now if turned on'=>'Saqlang va yoqilgan bo\'lsa, hoziroq tekshiring','a newer list was installed'=>'yangiroq ro\'yxat o\'rnatildi','already up to date'=>'allaqachon yangilangan','the download failed the signature check and was ignored'=>'yuklab olish imzo tekshiruvidan o‘tmadi va e’tiborga olinmadi','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® bilan bog‘lanib bo‘lmadi; joriy ro‘yxat ishlatilishda davom etadi','turned off'=>'o\'chirilgan','Open'=>'Ochish','Check their status page'=>'Ularning holat sahifasini tekshiring','Open your billing page'=>'Hisob-kitob sahifangizni oching','Open your API keys page'=>'API kalitlari sahifasini oching','Open the AI settings'=>'Sunʼiy intellekt sozlamalarini ochish','Sorry, you are not allowed to do that.'=>'Kechirasiz, buni qilishga ruxsatingiz yo\'q.','Unknown provider.'=>'Noma\'lum provayder.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Xizmatingiz manzilini kiriting, masalan http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Bu API kalitiga o\'xshamaydi. Uni probelsiz holda qaytadan nusxalang.','Paste your API key first.'=>'Avval API kalitingizni joylashtiring.','Key removed.'=>'Kalit olib tashlandi.','Models saved.'=>'Modellar saqlandi.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Modelning aniq nomini kiriting, masalan, provayder hujjatlarida yozilganidek.','Added %s. Choose it under "Which model to use".'=>'%s qoʻshildi. Uni "Qaysi modeldan foydalanish" ostidan tanlang.','Model removed.'=>'Model olib tashlandi.','Daily updates are off. The list that came with the plugin is used.'=>'Kunlik yangilanishlar o‘chirilgan. Plagin bilan birga kelgan ro‘yxat ishlatiladi.','Checked: %s.'=>'Tekshirildi: %s.','Model lists refreshed.'=>'Model roʻyxatlari yangilandi.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Sizning sun\'iy intellekt kalitingiz plaginlaringizdan birining yangiroq versiyasi tomonidan saqlangan. Ushbu plaginni yangilang yoki sun\'iy intellekt sozlamalarida kalitni qaytadan kiriting.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Saqlangan sun\'iy intellekt kalitingizni endi ochib bo\'lmaydi (saytning xavfsizlik kalitlari o\'zgargan). Uni sun\'iy intellekt sozlamalarida qaytadan kiriting.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'SUN\'iy intellekt hali sozlangan emas. AI sozlamalarida sun\'iy intellekt provayderi uchun kalit qo\'shing.','No model is chosen for this task. Pick one in the AI settings.'=>'Bu vazifa uchun model tanlanmagan. AI sozlamalaridan birini tanlang.','That AI provider is not supported by this version of the plugin.'=>'Bu sun\'iy intellekt provayderi plaginning ushbu versiyasi tomonidan qo\'llab-quvvatlanmaydi.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Bu sayt sun\'iy intellekt xizmatingizga ulanolmadi. U ishlayotganini va uning manziliga veb-serveringizdan kirish mumkinligini tekshiring (o\'z kompyuteringizdagi xizmatga xostingdagi saytdan kirib bo\'lmaydi).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Bu sayt %s manziliga ulanib bo‘lmadi. Ularning holat sahifasini tekshiring; agar ular ishlayotgan bo‘lsa, xostingiz chiquvchi ulanishlarni bloklayotgan bo‘lishi mumkin yoki manzil noto‘g‘ri.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s hisobingizda mablag‘ yoki kvota qolmaganini bildiradi. Ularning hisobingizdagi mablag‘ni to‘ldiring yoki limitni oshiring, so‘ngra qaytadan urinib ko‘ring.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s kalitingizni qabul qilmadi. U xato kiritilgan, bekor qilingan yoki muddati tugagan bo\'lishi mumkin. Yangi kalit yarating va uni shu yerga qo\'ying.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s kalitingiz uchun qilingan ushbu soʻrovni rad etdi. Kalit ushbu model yoki funksiyaga kirish huquqiga ega boʻlmasligi mumkin yoxud hisobingizni tasdiqlash talab etiladi.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'"%1$s" modeli kalitingiz uchun %2$s tomonidan taqdim etilmaydi. Sun\'iy intellekt sozlamalaridan boshqa modelni tanlang.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s kalitingiz soʻrov yuborish tezligini cheklamoqda. Bir daqiqa kuting va qayta urinib koʻring yoki ular bilan tarifingizdagi soʻrovlar limitini oshiring.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s hozirda muammolarga duch kelmoqda (ularning tomonidan uzilish yoki ortiqcha yuklanish). Sozlamalaringizda hech qanday xatolik yo\'q. Ozgina vaqt o\'tib qayta urinib ko\'ring.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Sun\'iy intellekt so\'rovi biz aniqlay olmagan sababga ko\'ra bajarilmadi. Qaytadan urinib ko\'ring; agar bu holat takrorlanaversa, quyidagi tafsilotlar bilan qo\'llab-quvvatlash xizmatiga murojaat qiling.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Sun\'iy intellekt provayderi ushbu plagin o\'qiy olmaydigan shaklda javob berdi. Qayta urinib ko\'ring; agar muammo takrorlansa, boshqa modelni tanlang yoki qo\'llab-quvvatlash xizmatiga murojaat qiling.','Custom (OpenAI-compatible)'=>'Maxsus (OpenAI-mos)','Save a key for this provider first.'=>'Avval ushbu provayder uchun kalitni saqlang.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Kalitingiz ishlayapti, lekin provayder u uchun hech qanday matn modelini ko\'rsatmagan. Quyida o\'zingiz model qo\'shing.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Ulandi. %1$s %2$s yordamida javob berdi. Sun\'iy intellekt funksiyalaringiz foydalanishga tayyor.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Sizning foydalanuvchi rolingizga ushbu saytda sun\'iy intellektdan foydalanishga ruxsat etilmagan. Administratorga murojaat qiling.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ushbu sayt oylik sun\'iy intellekt xarajatlari limitiga yetdi. Administrator uni sun\'iy intellekt sozlamalarida oshirishi mumkin.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ushbu sayt sun\'iy intellekt so\'rovlarining oylik limitiga yetdi. Administrator buni sun\'iy intellekt sozlamalarida oshirishi mumkin.','Usage and cost'=>'Foydalanish va narx','The log, limits and role permissions apply to AI used through: %s.'=>'Jurnal, limitlar va rol ruxsatlari quyidagi orqali ishlatiladigan sun\'iy intellektga nisbatan qo\'llaniladi: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Xarajatlar taxminiy bo‘lib, e’lon qilingan narxlardan kelib chiqqan holda hisoblangan; narxi noma’lum bo‘lgan model nolga teng deb olinadi.','This month: %1$s requests, about %2$s.'=>'Shu oy: %1$s ta so‘rov, taxminan %2$s.','When'=>'Qachon','Who'=>'Kim','Used for'=>'Ishlatiladi','Model'=>'Model','Tokens in / out'=>'Kirish / chiqish tokenlari','About'=>'Haqida','Result'=>'Natija','No AI requests have been made yet.'=>'Hali suniy intellekt so‘rovlari yuborilmagan.','Done'=>'Bajarildi','Limits and permissions'=>'Chegaralar va ruxsatlar','Monthly spending limit (US dollars)'=>'Oylik xarajat limiti (US dollari)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Cheklov qo\'ymaslik uchun bo\'sh qoldiring. Taxminiy xarajat unga yetganda, sun\'iy intellekt oyning qolgan qismi uchun to\'xtaydi.','Monthly request limit'=>'Oylik so‘rovlar limiti','Leave empty for no limit.'=>'Cheklash qo\'ymaslik uchun bo\'sh qoldiring.','Who may use AI'=>'AI-dan kimlar foydalanishi mumkin','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Plagin funksiyalaridan foydalana oladigan har bir kishi sun\'iy intellektni ishlatishiga ruxsat berish uchun hech birini belimang. Administratorlar undan doimiy ravishda foydalanishi mumkin.','Save limits and permissions'=>'Cheklovlar va ruxsatlarni saqlash','Limits and permissions saved.'=>'Chegaralar va ruxsatlar saqlandi.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Plaginning ushbu nusxasida admin ekranining skriptlari mavjud emas. Uni chiqarilgan paketdan qayta o‘rnating.','This screen needs JavaScript.'=>'Ushbu ekran uchun JavaScript talab qilinadi.','Choose a language'=>'Tilni tanlang','Upgrade'=>'Yangilash','Pricing'=>'Narxlar','Start Trial'=>'Sinov muddatini boshlash','Account'=>'Hisob','Contact Us'=>'Biz bilan bog\'laning','Affiliation'=>'Hamkorlik','the kind of softwarePlugin'=>'Plagin','greetingHey %s,'=>'Salom %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Xavfsizlik va funksiya yangilanishlari, ta’limiy kontent va vaqti-vaqti bilan taqdim etiladigan takliflar bo‘yicha elektron pochta xabarnomalarini olish hamda asosiy WordPress muhiti haqida ayrim ma’lumotlarni ulashish uchun rozilik bildiring. Bu bizga %s\'ni saytingizga moslashuvchanroq qilishga va sizga kerakli vazifalarni yanada yaxshiroq bajarishiga yordam beradi.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Xavfsizlik va funksiya yangilanishlari, ta\'limiy kontent hamda vaqti-vaqti bilan taqdim etiladigan takliflar bo\'yicha elektron pochta xabarnomalarini olish hamda ba\'zi asosiy WordPress muhiti ma\'lumotlarini ulashish uchun ro\'yxatdan o\'ting.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Buni o\'tkazib yuborsangiz ham muammo yo\'q! %1$s baribir yaxshi ishlayveradi.','Allow & Continue'=>'Ruxsat berish va davom etish','verbSkip'=>'Oʻtkazib yuborish','Skipping, please wait'=>'O\'tkazib yuborilmoqda, iltimos kuting','Continue'=>'Davom etish','Please wait'=>'Iltimos, kuting','as activating pluginActivating'=>'Faollashtirilmoqda','This will allow %s to'=>'Bu %s ga quyidagilarga ruxsat beradi','Privacy Policy'=>'Maxfiylik siyosati','Terms of Service'=>'Foydalanish shartlari','License Agreement'=>'Litsenziya shartnomasi','Have a license key?'=>'Litsenziya kalitingiz bormi?','Activate License'=>'Litsenziyani faollashtirish','View Basic Profile Info'=>'Asosiy profil ma\'lumotlarini ko\'rish','Your WordPress user\'s: first & last name, and email address'=>'Sizning WordPress foydalanuvchingizning: ismi va familiyasi hamda elektron pochta manzili','View Basic Website Info'=>'Veb-saytning asosiy ma\'lumotlarini ko\'rish','Homepage URL & title, WP & PHP versions, and site language'=>'Bosh sahifa URL manzili va sarlavhasi, WP va PHP versiyalari hamda sayt tili','View Basic %s Info'=>'Asosiy %s maʼlumotlarini koʻrish','Current %s & SDK versions, and if active or uninstalled'=>'Joriy %s va SDK versiyalari, shuningdek ular faol yoki o\'chirilganligi','Newsletter'=>'Axborotnoma','Updates, announcements, marketing, no spam'=>'Yangilanishlar, e\'lonlar, marketing, spam yo\'q','View Diagnostic Info'=>'Diagnostika ma\'lumotlarini ko\'rish','WordPress & PHP versions, site language & title'=>'WordPress va PHP versiyalari, sayt tili va sarlavhasi','View Plugins & Themes List'=>'Plaginlar va mavzular ro\'yxatini ko\'rish','Names, slugs, versions, and if active or not'=>'Nomi, sluglar, versiyalar va ular faol yoki faol emasligi','optional'=>'ixtiyoriy','Never miss an important update'=>'Muhim yangilanishni hech qachon o\'tkazib yubormang','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Biz ushbu qo‘shilish imkoniyatini taqdim etdik, shunda siz hech qanday muhim yangilanishni o‘tkazib yubormaysiz va %s vositasini veb-saytingizga moslashuvchanroq qilishimizda hamda sizga kerakli vazifalarni bajarishda yaxshiroq ishlashiga yordam berasiz.','Thank you for updating to %1$s v%2$s!'=>'%1$s v%2$s versiyasiga yanginganingiz uchun rahmat!','That language is not one of this site\'s languages.'=>'Bu til ushbu sayt tillaridan biri emas.','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks 1 dan 8 gacha kichik harflar yoki raqamlardan iborat bo\'lishi, harf bilan boshlanishi va plagin nomiga teng bo\'lmasligi kerak.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" til kodi emas. fr_FR yoki de_DE kabi WordPress til muhitidan foydalaning.','List at least one language.'=>'Kamida bitta tilni ko\'rsating.','That is more languages than one site can list.'=>'Bu bitta sayt roʻyxatga olishi mumkin boʻlganidan koʻra koʻproq tillardir.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Zinn Digital® Ltd kompaniyasi bosh direktori Neil Lock tomonidan yaratilgan','Version %s'=>'Versiya %s','Tranzly website'=>'Tranzly veb-sayti','Zinn Digital® website'=>'Zinn Digital® veb-sayti','Settings saved.'=>'Sozlamalar saqlandi.','See the Pro plans and pricing'=>'Pro rejalar va narxlarni ko\'rish','Languages'=>'Tillar','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Birinchi til — kontentingiz yozilgan til. Tashrif buyuruvchilar tilni almashtirish bloki yordamida o‘tishadi.','(default)'=>'(standart)','Locale code'=>'Til kodi','For example fr_FR'=>'Masalan fr_FR','Name (optional)'=>'Ism (ixtiyoriy)','For example Français'=>'Masalan Français','Add language'=>'Til qo\'shish','Front-end output'=>'Old tomon chiqishi','Class name prefix'=>'Klass nomi prefiksi','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Plagin sahifalaringizda chop etadigan har bir klass nomi shu prefiks bilan boshlanadi, shunda sahifalar qaysi plagin tomonidan yaratilganini oshkor qilmaydi. Harf bilan boshlanadigan 1 dan 8 gacha bo\'lgan kichik harflar yoki raqamlar.','Beta updates'=>'Beta yangilanishlar','This site receives beta versions as updates.'=>'Bu sayt yangilanish sifatida beta-versiyalarni qabul qiladi.','This site receives stable versions only.'=>'Ushbu sayt faqat barqaror versiyalarni qabul qiladi.','Change this on the Account page'=>'Buni Hisob sahifasida o\'zgartiring','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta versiyalar o\'z hisobiga ulangan litsenziyaga ega Pro o\'rnatishlariga taklif etiladi. Ulangandan so\'ng, Hisob sahifasidan qo\'shilishingiz mumkin.','Save settings'=>'Sozlamalarni saqlash','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Boshqaruv menyusida Tranzly ostida ikkinchi tilni qo\'shing va o\'tkazgich shu yerda paydo bo\'ladi.','Switcher'=>'Almashtirgich','Accessible label'=>'Ochiq yorliq','block titleLanguage switcher'=>'Tilni o\'zgartirgich','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Saytning har bir tilidagi ushbu sahifaga havolalar. Ikki yoki undan ortiq tillar ko\'rsatilmaguncha u hech narsa ko\'rsatmaydi.','block keywordlanguage'=>'Til','block keywordswitcher'=>'almashtirgich','block keywordtranslation'=>'tarjima']];